def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    bg = max(range(10), key=lambda value: counts[value])

    sep_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != bg
    ]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != bg
    ]

    def ranges(size, separators):
        result = []
        start = 0
        for pos in separators:
            if start < pos:
                result.append((start, pos))
            start = pos + 1
        if start < size:
            result.append((start, size))
        return result

    row_ranges = ranges(h, sep_rows)
    col_ranges = ranges(w, sep_cols)

    # Use the panel with the most non-background cells as the pattern source.
    panels = []
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            score = sum(
                grid[r][c] != bg
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            panels.append((score, ri, ci))

    _, src_ri, src_ci = max(panels)
    sr0, sr1 = row_ranges[src_ri]
    sc0, sc1 = col_ranges[src_ci]

    out = [row[:] for row in grid]
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    rr = sr0 + (r - r0)
                    cc = sc0 + (c - c0)
                    if rr < sr1 and cc < sc1:
                        out[r][c] = grid[rr][cc]
    return out
